1	/**
2	 * Screen 05 test W11, material factor (`?flow05=1` / `?river05=1`): flow map + ripple map for the 05 river.
3	 *
4	 * FLOW MAP "from curves" (flowField05): a small RGBA8 texture over the river's own (u, s) domain — u across the
5	 * ribbon (−1 … 1 = bank to bank), s along the master course through stage 05 — generated at load time from the SAME
6	 * curves the game rides and draws: the course spline (course.ts meander05), the visible channel (channel05), the
7	 * cyan-core swing (coreLateral + coreShiftW10) and the magenta bands' S (sbend05). Every texel holds the local flow:
8	 *   R  lateral flow per unit travelled downstream (± FLOW_LAT_RANGE): the streamline through the texel keeps its
9	 *      fraction between the core line and the bank, so the flow bends with every S-curve and squeezes through
10	 *      the narrows beside a foam shelf
11	 *   G  speed (0 … 1): fast in the core, slower toward the banks, a little faster on the outside of a bend,
12	 *      almost still on a foam shelf
13	 *   B  turbulence (0 … 1): bank shear + bends (brighter, busier ripples)
14	 *   A  phase noise (0 … 1): de-synchronises the two-phase cycle from place to place (no visible pulse)
15	 * The fragment shaders (waterRibbon.ts, materials.ts farRiverMaterial) use it exactly like three.js Water2 uses its
16	 * `flowMap`: two samples of a tileable normal map are carried along the flow vector for one cycle each, half a cycle
17	 * apart, and cross-faded — but on the game's spline ribbon, without Water2's reflection / refraction render passes
18	 * (a planar mirror cannot follow a winding, banked stream and doubles the draw calls on a phone).
19	 *
20	 * RIPPLE MAP (rippleMap05): tileable 128² normal (RG) + height (B) + crest (A) texture, a deterministic sum of
21	 * integer-frequency waves (exactly periodic, mip-mapped). The same data can be replaced later by an authored map
22	 * (Blender bake, JangaFX IlluGen export): `scripts/flow05-dump.ts` writes both textures as PNG.
23	 *
24	 * Nothing here runs unless the switch is on (FLOWMAP05), so the default build is untouched.
25	 */
26	import * as THREE from 'three';
27	import type { Course } from '../world/course';
28	import { channel05, coreLateral, coreShiftW10, sbend05 } from './waterRibbon';
29	
30	/** lateral flow (units per unit downstream) encoded in R as 0.5 + v / (2·range) */
31	export const FLOW_LAT_RANGE = 0.6;
32	export const FLOW_W = 32;
33	export const FLOW_H = 256;
34	export const RIPPLE_N = 128;
35	
36	function mulberry32(seed: number) {
37	  let a = seed >>> 0;
38	  return () => {
39	    a = (a + 0x6d2b79f5) >>> 0;
40	    let t = a;
41	    t = Math.imul(t ^ (t >>> 15), t | 1);
42	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
43	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
44	  };
45	}
46	const smooth = (a: number, b: number, x: number) => {
47	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
48	  return t * t * (3 - 2 * t);
49	};
50	
51	export interface FlowField05 {
52	  /** RGBA8, FLOW_W × FLOW_H, row 0 = s0 */
53	  data: Uint8Array<ArrayBuffer>;
54	  /** arc length of the first row and the covered length (v = (s − s0) / len) */
55	  s0: number;
56	  len: number;
57	}
58	
59	/** the river's flow field, straight from its curves (pure data: also used by the QA dump in node) */
60	export function flowField05(course: Course): FlowField05 {
61	  const st = course.stage('05');
62	  const s0 = st.s0 - 2, len = st.s1 + 6 - s0;
63	  const data = new Uint8Array(new ArrayBuffer(FLOW_W * FLOW_H * 4));
64	  const rnd = mulberry32(0x05f10a);
65	  // low-frequency phase noise lattice (bilinear), 5 × 33 knots
66	  const NX = 5, NY = 33;
67	  const lattice = Array.from({ length: NX * NY }, () => rnd());
68	  const phase = (fx: number, fy: number) => {
69	    const x = fx * (NX - 1), y = fy * (NY - 1);
70	    const i = Math.min(NX - 2, Math.floor(x)), j = Math.min(NY - 2, Math.floor(y));
71	    const tx = x - i, ty = y - j;
72	    const g = (a: number, b: number) => lattice[b * NX + a];
73	    return (g(i, j) * (1 - tx) + g(i + 1, j) * tx) * (1 - ty) + (g(i, j + 1) * (1 - tx) + g(i + 1, j + 1) * tx) * ty;
74	  };
75	  const w05 = (s: number) => smooth(st.s0 - 5, st.s0 + 5, s) * (1 - smooth(st.s1 - 5, st.s1 + 5, s));
76	  /** core line, channel edges (ribbon lateral units) at s */
77	  const lines = (s: number) => {
78	    const ch = channel05(course, s);
79	    const core = coreLateral(course, s) + coreShiftW10(course, s) + sbend05(s) * w05(s);
80	    const eL = ch.c - ch.hw, eR = ch.c + ch.hw;
81	    return { core: Math.min(eR - 0.8, Math.max(eL + 0.8, core)), eL, eR };
82	  };
83	  const D = 0.3;
84	  for (let j = 0; j < FLOW_H; j++) {
85	    const s = s0 + ((j + 0.5) / FLOW_H) * len;
86	    const hwFull = course.widthAt(s) / 2;
87	    const a = lines(s - D), m = lines(s), b = lines(s + D);
88	    const bend = (b.core - a.core) / (2 * D);                  // heading of the core line (lateral per unit s)
89	    const curv = (b.core - 2 * m.core + a.core) / (D * D);
90	    for (let i = 0; i < FLOW_W; i++) {
91	      const u = -1 + (2 * (i + 0.5)) / FLOW_W;
92	      const lat = u * hwFull;
93	      let dl: number, spd: number, turb: number;
94	      if (lat < m.eL || lat > m.eR) {
95	        // foam shelf: almost still, creeping along the bank line
96	        const eA = lat < m.eL ? a.eL : a.eR, eB = lat < m.eL ? b.eL : b.eR;
97	        dl = (0.5 * (eB - eA)) / (2 * D);
98	        spd = 0.08;
99	        turb = 0.2;
100	      } else {
101	        const right = lat >= m.core;
102	        const t = right ? (lat - m.core) / Math.max(0.3, m.eR - m.core) : (m.core - lat) / Math.max(0.3, m.core - m.eL);
103	        // the streamline keeps its fraction t between the core line and its bank
104	        const la = right ? a.core + t * (a.eR - a.core) : a.core - t * (a.core - a.eL);
105	        const lb = right ? b.core + t * (b.eR - b.core) : b.core - t * (b.core - b.eL);
106	        dl = (lb - la) / (2 * D);
107	        // outside of a bend runs faster (the core line curves away from it)
108	        const outer = Math.max(-1, Math.min(1, -curv * 6)) * (right ? 1 : -1);
109	        spd = Math.min(1, (0.46 + 0.54 * (1 - t * t)) * (1 + 0.16 * outer * t));
110	        turb = Math.min(1, 0.85 * smooth(0.55, 1, t) + 0.9 * Math.abs(bend));
111	      }
112	      const k = (j * FLOW_W + i) * 4;
113	      data[k] = Math.round(255 * Math.min(1, Math.max(0, 0.5 + dl / (2 * FLOW_LAT_RANGE))));
114	      data[k + 1] = Math.round(255 * spd);
115	      data[k + 2] = Math.round(255 * turb);
116	      data[k + 3] = Math.round(255 * phase((i + 0.5) / FLOW_W, (j + 0.5) / FLOW_H));
117	    }
118	  }
119	  return { data, s0, len };
120	}
121	
122	/** tileable ripple map: RG = normal xy (0.5 + 0.5 n), B = height 0..1, A = crest mask (sharp bright wave tops) */
123	export function rippleData05(N = RIPPLE_N): Uint8Array<ArrayBuffer> {
124	  const rnd = mulberry32(0x21b6e5);
125	  const waves: { kx: number; ky: number; a: number; ph: number; sharp: number }[] = [];
126	  // 20 smooth waves, |k| 2 … 8 cycles per tile, more of them ACROSS the flow axis (x) than along it. The shaders
127	  // stretch the tile ≈26:1 along the river (2.4 u × 62 u), so the crests read as long satin streaks (approved image:
128	  // streaks ≈0.15 u wide and 7–20 u long) — no fine grain, which read as static on the first W11 render
129	  while (waves.length < 20) {
130	    const kx = Math.round((rnd() * 2 - 1) * 8), ky = Math.round((rnd() * 2 - 1) * 4);
131	    const kk = Math.hypot(kx, ky);
132	    if (kk < 2 || kk > 8.5 || kx === 0) continue;
133	    waves.push({ kx, ky, a: 1 / Math.pow(kk, 1.3), ph: rnd() * Math.PI * 2, sharp: 1.3 + rnd() * 1.4 });
134	  }
135	  const h = new Float32Array(N * N);
136	  let lo = Infinity, hi = -Infinity;
137	  for (let y = 0; y < N; y++) {
138	    for (let x = 0; x < N; x++) {
139	      let v = 0;
140	      for (const w of waves) {
141	        const c = 0.5 + 0.5 * Math.cos((2 * Math.PI * (w.kx * x + w.ky * y)) / N + w.ph);
142	        v += w.a * Math.pow(c, w.sharp);                      // narrow crests, broad troughs
143	      }
144	      h[y * N + x] = v;
145	      if (v < lo) lo = v;
146	      if (v > hi) hi = v;
147	    }
148	  }
149	  const out = new Uint8Array(new ArrayBuffer(N * N * 4));
150	  const at = (x: number, y: number) => (h[((y + N) % N) * N + ((x + N) % N)] - lo) / (hi - lo);
151	  for (let y = 0; y < N; y++) {
152	    for (let x = 0; x < N; x++) {
153	      const v = at(x, y);
154	      const gx = (at(x + 1, y) - at(x - 1, y)) * 0.5 * N, gy = (at(x, y + 1) - at(x, y - 1)) * 0.5 * N;
155	      // slopes are ≈ ±8 per tile: 0.07 keeps |n.xy| mostly under 0.6
156	      const nx = -gx * 0.07, ny = -gy * 0.07;
157	      const il = 1 / Math.hypot(nx, ny, 1);
158	      const k = (y * N + x) * 4;
159	      out[k] = Math.round(255 * (0.5 + 0.5 * nx * il));
160	      out[k + 1] = Math.round(255 * (0.5 + 0.5 * ny * il));
161	      out[k + 2] = Math.round(255 * v);
162	      out[k + 3] = Math.round(255 * smooth(0.66, 0.9, v));
163	    }
164	  }
165	  return out;
166	}
167	
168	export interface Flow05 {
169	  flowMap: THREE.DataTexture;
170	  ripple: THREE.DataTexture;
171	  /** x = s0, y = 1 / len (flow-map v = (s − x) · y) */
172	  sRange: THREE.Vector2;
173	}
174	let cache: Flow05 | null = null;
175	/** the two GPU textures (built once; 32×256 + 128² RGBA8 ≈ 0.1 MB with mips) */
176	export function flow05Textures(course: Course): Flow05 {
177	  if (cache) return cache;
178	  const ff = flowField05(course);
179	  // three's texture UUIDs draw on Math.random: keep the global sequence untouched (see marblePano05)
180	  const rndG = Math.random;
181	  Math.random = () => 0.5;
182	  let flowMap: THREE.DataTexture, ripple: THREE.DataTexture;
183	  try {
184	    flowMap = new THREE.DataTexture(ff.data, FLOW_W, FLOW_H, THREE.RGBAFormat, THREE.UnsignedByteType);
185	    ripple = new THREE.DataTexture(rippleData05(), RIPPLE_N, RIPPLE_N, THREE.RGBAFormat, THREE.UnsignedByteType);
186	  } finally {
187	    Math.random = rndG;
188	  }
189	  flowMap.uuid = 'flow05-map';
190	  flowMap.name = 'flow05_map';
191	  flowMap.magFilter = flowMap.minFilter = THREE.LinearFilter;
192	  flowMap.wrapS = flowMap.wrapT = THREE.ClampToEdgeWrapping;
193	  flowMap.colorSpace = THREE.NoColorSpace;
194	  flowMap.needsUpdate = true;
195	  ripple.uuid = 'flow05-ripple';
196	  ripple.name = 'flow05_ripple';
197	  ripple.wrapS = ripple.wrapT = THREE.RepeatWrapping;
198	  ripple.magFilter = THREE.LinearFilter;
199	  ripple.minFilter = THREE.LinearMipmapLinearFilter;
200	  ripple.generateMipmaps = true;
201	  ripple.anisotropy = 4;
202	  ripple.colorSpace = THREE.NoColorSpace;
203	  ripple.needsUpdate = true;
204	  cache = { flowMap, ripple, sRange: new THREE.Vector2(ff.s0, 1 / ff.len) };
205	  return cache;
206	}
207	
208	/**
209	 * Uniform objects shared between the ribbon (vfx) and the 05 tunnel (world): the game clock the ribbon is driven
210	 * with (so the far river animates in step), and the Marble panorama (set by environment.ts, which owns it).
211	 */
212	export const flow05Shared = {
213	  uTime: { value: 0 } as THREE.IUniform<number>,
214	  uPano: { value: null } as THREE.IUniform<THREE.Texture | null>,
215	  /** world direction → panorama lookup direction (materials.ts marblePanoMatrix05) */
216	  uPanoRot: { value: new THREE.Matrix3() } as THREE.IUniform<THREE.Matrix3>,
217	};
218	
219	/**
220	 * GLSL (fragment): two-phase flow-map sampling of the ripple map, the three.js Water2 scheme. `uv` = ripple uv at
221	 * rest, `adv` = uv travelled along the flow during one cycle, `cyc` = cycle counter (time / period + phase noise).
222	 * Each phase is centred on its rest position (offset −½ … +½ cycle), so it is least distorted when its weight peaks.
223	 */
224	export const FLOW05_GLSL = /* glsl */ `
225	vec4 flowRipple(sampler2D map, vec2 uv, vec2 adv, float cyc) {
226	  float p0 = fract(cyc), p1 = fract(cyc + 0.5);
227	  vec4 a = texture2D(map, uv - adv * (p0 - 0.5));
228	  vec4 b = texture2D(map, uv - adv * (p1 - 0.5) + vec2(0.37, 0.61));
229	  return mix(b, a, 1.0 - abs(1.0 - 2.0 * p0));
230	}
231	`;
232

