861	export function farRiverMaterial(glow: FarGlow, d0 = 53.25, flow?: { ripple: THREE.Texture; time: THREE.IUniform; speed: number }): THREE.MeshBasicMaterial {
862	  const mat = new THREE.MeshBasicMaterial({ color: '#ffffff', fog: false });
863	  // wins the depth test against the real ribbon's continuation it covers just behind the seam
864	  mat.polygonOffset = true;
865	  mat.polygonOffsetFactor = -1;
866	  mat.polygonOffsetUnits = -2;
867	  const lin = (r: number, g: number, b: number) => new THREE.Color().setRGB(r, g, b, THREE.LinearSRGBColorSpace);
868	  const uniforms = {
869	    uRivCyanLo: { value: lin(0.02, 0.22, 0.62) },
870	    uRivCyan: { value: lin(0.03, 0.42, 0.95) },
871	    uRivCyanHi: { value: lin(0.25, 0.95, 1.6) },
872	    uRivPinkLo: { value: lin(0.45, 0.03, 0.42) },
873	    uRivPink: { value: lin(0.85, 0.07, 0.75) },
874	    uRivPinkHi: { value: lin(1.05, 0.42, 1.0) },
875	    uRivFoam: { value: lin(0.95, 0.92, 1.05) },
876	    uRivFoamLav: { value: lin(0.62, 0.52, 0.95) },
877	    uRivFoamBlue: { value: lin(0.32, 0.36, 0.9) },
878	    uRivGlow: { value: new THREE.Color(glow.color) },
879	    uRivGlowR: { value: new THREE.Vector3(glow.near, glow.far, glow.strength) },
880	    /** W11: depth of the seam from the locked 05 eye (ForcedTunnel.D0) — screen-isotropic foam cells */
881	    uRivD0: { value: d0 },
882	    ...(flow ? { uRivRipple: { value: flow.ripple }, uRivTime: flow.time, uRivFlow: { value: flow.speed } } : {}),
883	  };
884	  mat.onBeforeCompile = (shader) => {
885	    Object.assign(shader.uniforms, uniforms);
886	    shader.vertexShader = shader.vertexShader
887	      .replace('#include <common>', `#include <common>
888	attribute float fgExtra; attribute float aRivLat; attribute vec4 aRivA; attribute vec4 aRivB;
889	varying float vRivDist; varying vec2 vRivUv; varying float vRivLat; varying vec4 vRivA; varying vec4 vRivB;`)
890	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvRivUv = uv; vRivLat = aRivLat; vRivA = aRivA; vRivB = aRivB;')
891	      .replace('#include <project_vertex>', '#include <project_vertex>\nvRivDist = length(mvPosition.xyz) + fgExtra;');
892	    shader.fragmentShader = shader.fragmentShader
893	      .replace('#include <common>', `#include <common>
894	varying float vRivDist; varying vec2 vRivUv; varying float vRivLat; varying vec4 vRivA; varying vec4 vRivB;
895	uniform vec3 uRivCyanLo; uniform vec3 uRivCyan; uniform vec3 uRivCyanHi; uniform vec3 uRivPinkLo; uniform vec3 uRivPink; uniform vec3 uRivPinkHi;
896	uniform vec3 uRivFoam; uniform vec3 uRivFoamLav; uniform vec3 uRivFoamBlue; uniform vec3 uRivGlow; uniform vec3 uRivGlowR;
897	#ifdef FARW05
898	uniform float uRivD0;
