  float xq = lat - core;
  float dL = abs(lat - cL), dR = abs(lat - cR);
  float pL = 1.0 - smoothstep(wL - aaw, wL + aaw, dL);
  float pR = 1.0 - smoothstep(wR - aaw, wR + aaw, dR);
