  cy = mix(cy, uRivCyanHi, clamp(lines * smoothstep(0.35, 0.8, dn) * 0.85 + lines2 * 0.75, 0.0, 1.0));
  lines = max(lines, lines2);
  float rimOut = (1.0 - pink) * max(1.0 - smoothstep(wL, wL + 0.3, dL), 1.0 - smoothstep(wR, wR + 0.3, dR));
