  vec3 pk = mix(uRivPinkLo, uRivPink, smoothstep(-0.95, -0.2, relB));
  pk = mix(pk, uRivPinkHi, clamp(satin * 0.5 + lines * 0.35, 0.0, 1.0));
  vec3 col = mix(cy, pk, pink);
