    float c = rivCells(vec2(lat * 5.5, s * 2.4 + lat * 0.7));
    float cf = 1.0 - smoothstep(0.08, 0.22, fl * 5.5);    // bubble cells only where they are ≳ 3 px
    float bub = mix(0.5, smoothstep(0.12, 0.8, c), cf);
