598	    /** QA: on-screen centre (px) and diameter (px) of every untaken coin in front of the camera */
599	    coinScreen() {
600	      const mesh = coins.group.children[0] as THREE.InstancedMesh;
601	      const m = new THREE.Matrix4(), p = new THREE.Vector3(), q = new THREE.Quaternion(), sc = new THREE.Vector3();
602	      const W = renderer.domElement.clientWidth, H = renderer.domElement.clientHeight;
603	      camera.updateMatrixWorld();
604	      const right = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0);
605	      const out: { i: number; x: number; y: number; d: number }[] = [];
606	      coins.defs.forEach((_, i) => {
607	        if (coins.collected[i]) return;
608	        mesh.getMatrixAt(i, m); m.decompose(p, q, sc);
609	        const c = p.clone().project(camera);
610	        if (c.z > 1 || c.z < -1) return;
611	        const e = p.clone().addScaledVector(right, 0.5 * sc.x).project(camera);
612	        const x = ((c.x + 1) / 2) * W, y = ((1 - c.y) / 2) * H;
613	        if (x < -50 || x > W + 50 || y < -50 || y > H + 50) return;
614	        out.push({ i, x: Math.round(x), y: Math.round(y), d: Math.round((e.x - c.x) * W) });
615	      });
616	      return out;
617	    },
618	    respawns() { return st.respawns; },
619	    /** QA (camera lock): the live render camera — world matrix (column-major), vertical fov, aspect, near/far */
620	    camera() {
