622	      const W = renderer.domElement.clientWidth, H = renderer.domElement.clientHeight;
623	      return { matrixWorld: camera.matrixWorld.toArray(), fov: camera.fov, aspect: camera.aspect, near: camera.near, far: camera.far, width: W, height: H, position: camera.position.toArray(), target: rideCam.target.toArray() };
624	    },
625	    /** debug: Benny's projected screen position (NDC -1..1, z<1 = in front of camera) */
626	    bennyScreen() {
627	      const v = benny.root.getWorldPosition(new THREE.Vector3()).project(camera);
628	      return { x: +v.x.toFixed(2), y: +v.y.toFixed(2), z: +v.z.toFixed(3), visible: benny.root.visible, cam: camera.position.toArray().map((q) => +q.toFixed(2)), benny: benny.root.position.toArray().map((q) => +q.toFixed(2)) };
629	    },
630	    /** debug: what does a ray from the camera through NDC (x,y) hit first? */
631	    probe(x = 0, y = 0) {
632	      const rc = new THREE.Raycaster();
